set local role service_role;do $$declare a uuid;m uuid;x uuid;j uuid;b uuid;c uuid;d uuid;result jsonb;n uuid;docid uuid:=gen_random_uuid();lease uuid;denied boolean;contact text:='QA STATUS EMAIL '||gen_random_uuid();begin
insert into public.impjo_principals(kind,state,name) values('STAFF','APPROVED','QA STATUS EMAIL ADMIN') returning id into a;insert into public.impjo_roles values(a,'ADMIN'),(a,'OPERATOR');
insert into public.impjo_principals(kind,state,name) values('LINE','APPROVED','QA STATUS EMAIL MESS') returning id into m;insert into public.impjo_roles values(m,'MESS');
insert into public.impjo_principals(kind,state,name) values('LINE','APPROVED','QA STATUS EMAIL OTHER') returning id into x;insert into public.impjo_roles values(x,'MESS');
perform public.impjo_documents(a,'recipient_save',jsonb_build_object('contact_name',contact,'email','qa@example.invalid','enabled',true));
insert into public.impjo_jobs(contact,phone,purpose,created_by,job_date) values(contact,'0811111111','QA',a,current_date) returning id into j;
insert into public.impjo_bls(job_id,number,hbl,consignee,destination,status) values(j,'QA-STATUS-ISSUE','QA-HBL','QA-CONSIGNEE','QA-DESTINATION','IN_PROGRESS') returning id into b;
result:=public.impjo_api(m,'status',jsonb_build_object('bl_id',b,'status','ISSUE_REPORTED','detail','แจ้งวันนัดใหม่'));n:=(result->>'notification_id')::uuid;
assert n is not null,'No atomic notification';assert (select count(*) from public.impjo_status_notifications where bl_id=b)=1,'Notification duplicated';
assert (select payload->>'issueDetail'='แจ้งวันนัดใหม่' and payload->>'status'='ISSUE_REPORTED' from public.impjo_status_notifications where id=n),'Issue snapshot missing';
denied:=false;begin perform public.impjo_status_mail(x,'claim',jsonb_build_object('id',n));exception when no_data_found then denied:=true;end;assert denied,'Other MESS claimed notification';
result:=public.impjo_status_mail(m,'claim',jsonb_build_object('id',n));lease:=(result->>'lease')::uuid;assert result->>'to'='qa@example.invalid' and result->>'blNumber'='QA-STATUS-ISSUE','Recipient or BL mismatch';
assert (public.impjo_status_mail(m,'claim',jsonb_build_object('id',n))->>'skip')::boolean,'Duplicate lease';
perform public.impjo_status_mail(m,'finish',jsonb_build_object('id',n,'lease',lease,'state','ACCEPTED','provider_id','QA'));
assert public.impjo_status_mail(m,'claim',jsonb_build_object('id',n))->>'state'='ACCEPTED','Accepted resent';
insert into public.impjo_bls(job_id,number,consignee,destination,status) values(j,'QA-STATUS-DONE','QA','QA','IN_PROGRESS') returning id into c;
result:=public.impjo_api(m,'status',jsonb_build_object('bl_id',c,'status','COMPLETED'));n:=(result->>'notification_id')::uuid;assert n is not null,'Complete did not queue';
perform public.impjo_documents(a,'recipient_save',jsonb_build_object('contact_name',contact,'email','changed@example.invalid','enabled',true));
assert public.impjo_status_mail(m,'claim',jsonb_build_object('id',n))->>'state'='RECIPIENT_CHANGED','Stale email recipient used';
update public.impjo_document_recipients set enabled=false where contact_key=lower(contact);
insert into public.impjo_bls(job_id,number,consignee,destination,status) values(j,'QA-STATUS-NOEMAIL','QA','QA','IN_PROGRESS') returning id into d;
result:=public.impjo_api(m,'status',jsonb_build_object('bl_id',d,'status','COMPLETED'));n:=(result->>'notification_id')::uuid;
assert (select state='NO_RECIPIENT' from public.impjo_status_notifications where id=n),'Missing recipient not represented';
assert (select status='COMPLETED' from public.impjo_bls where id=d),'Email setup rolled back status';
perform public.impjo_documents(a,'recipient_save',jsonb_build_object('contact_name',contact,'email','qa@example.invalid','enabled',true));
perform public.impjo_documents(m,'reserve',jsonb_build_object('id',docid,'bl_id',b,'sha256',repeat('a',64),'pages',1,'bytes',100));
perform public.impjo_documents(m,'complete',jsonb_build_object('id',docid));
result:=public.impjo_documents(m,'context',jsonb_build_object('bl_id',b));
perform public.impjo_documents(m,'submit',jsonb_build_object('id',docid,'recipient_version',result->'recipient'->>'version'));
result:=public.impjo_documents(m,'claim',jsonb_build_object('id',docid,'channel','email'));
assert result->>'status'='ISSUE_REPORTED' and result->>'issue_detail'='แจ้งวันนัดใหม่','PDF mail missed current status/reason';
assert result->>'hbl'='QA-HBL' and result->>'destination'='QA-DESTINATION','PDF report details missing';
assert not has_function_privilege('anon','public.impjo_status_mail(uuid,text,jsonb)','EXECUTE'),'Anon RPC exposed';
assert not has_table_privilege('authenticated','public.impjo_status_notifications','SELECT'),'Client sees status outbox';
 delete from public.impjo_bls where job_id=j;delete from public.impjo_jobs where id=j;assert not exists(select 1 from public.impjo_status_notifications where bl_id in(b,c,d)),'Job deletion left status emails';
end $$;
